 * Serializes a request body for use in a Swagger "try it out" request.
 *
 * Swagger UI hands us a variety of body types depending on the operation's
 * content type. Only a subset of those map cleanly onto the plain-string
 * bodies that Bruno's Swagger proxy can forward, so unsupported types throw a
 * descriptive TypeError instead of being silently dropped or mangled.
 */

export const UNSUPPORTED_BODY_TYPE_CODE = 'UNSUPPORTED_BODY_TYPE';

/**
 * Builds the generic "this body type isn't supported" message used when we
 * want to explain the limitation and point at the supported alternatives.
 */
export const UNSUPPORTED_BODY_MESSAGE = (bodyTypeName) =>
  `${bodyTypeName} isn't supported in Bruno yet. Supported body types are JSON, URL-encoded forms, plain text.`;

const unsupported = (bodyType, message) => {
  const error = new TypeError(message);
  error.code = UNSUPPORTED_BODY_TYPE_CODE;
  error.bodyType = bodyType;
  return error;
};

const isInstanceOf = (value, ctorName) => {
  const Ctor = typeof globalThis !== 'undefined' ? globalThis[ctorName] : undefined;
  return typeof Ctor === 'function' && value instanceof Ctor;
};

const serializeBody = (body) => {
  if (body === null || body === undefined) {
    return undefined;
  }

  if (typeof body === 'string') {
    return body;
  }

  if (isInstanceOf(body, 'URLSearchParams')) {
    return body.toString();
  }

  if (isInstanceOf(body, 'FormData')) {
    throw unsupported(
      'FormData',
      `Multipart form data ${UNSUPPORTED_BODY_MESSAGE('(FormData)')} Create a Bruno request to send multipart form data.`
    );
  }

  // File must be checked before Blob because File extends Blob.
  if (isInstanceOf(body, 'File')) {
    throw unsupported(
      'File',
      `File upload ${UNSUPPORTED_BODY_MESSAGE('(File)')} Create a Bruno request to upload files.`
    );
  }

  if (isInstanceOf(body, 'Blob')) {
    throw unsupported(
      'Blob',
      `Binary file upload ${UNSUPPORTED_BODY_MESSAGE('(Blob)')} Create a Bruno request to send binary data.`
    );
  }

  if (isInstanceOf(body, 'ArrayBuffer')) {
    throw unsupported(
      'ArrayBuffer',
      `Binary data ${UNSUPPORTED_BODY_MESSAGE('(ArrayBuffer)')}`
    );
  }

  if (ArrayBuffer.isView(body) && !isInstanceOf(body, 'DataView')) {
    const bodyType = (body.constructor && body.constructor.name) || 'TypedArray';
    throw unsupported(bodyType, `Binary data ${UNSUPPORTED_BODY_MESSAGE(`(${bodyType})`)}`);
  }

  return body;
};

export default serializeBody;
